package top.aameow.management.controller;
import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import top.aameow.common.core.controller.BaseController;import top.aameow.common.core.domain.AjaxResult;import top.aameow.common.core.page.TableDataInfo;import top.aameow.management.mapper.EmployeeMapper;import top.aameow.management.service.WorkProjectService;import top.aameow.common.exception.ServiceException;import top.aameow.common.utils.SecurityUtils;import top.aameow.common.annotation.Log;import top.aameow.common.enums.BusinessType;
@RestController @RequestMapping("/management/employees") public class EmployeeController extends BaseController {
 @Autowired private EmployeeMapper mapper;
 @Autowired private top.aameow.management.service.ReportCredentialService credentials;
 @GetMapping("/{id}/materials") @PreAuthorize("@ss.hasPermi('management:credential:list')") public AjaxResult materials(@PathVariable Long id){if(mapper.get(id)==null)throw new ServiceException("员工不存在");return success(credentials.list().stream().filter(c->id.equals(WorkProjectService.number(c.get("employeeId")))).toList());}
 @GetMapping @PreAuthorize("@ss.hasPermi('management:employee:list')") public TableDataInfo list(@RequestParam Map<String,Object> q){startPage();return getDataTable(mapper.list(q));}
 @GetMapping("/options") @PreAuthorize("@ss.hasPermi('management:employee:list') or @ss.hasPermi('management:credential:edit') or @ss.hasPermi('management:credential:list')") public AjaxResult options(@RequestParam(defaultValue="") String name){return success(mapper.options(name.trim()));}
 @PostMapping @Transactional(rollbackFor=Exception.class) @PreAuthorize("@ss.hasPermi('management:employee:edit')") @Log(title="人员管理",businessType=BusinessType.UPDATE)
 public AjaxResult save(@RequestBody Map<String,Object> input){Map<String,Object> v=new HashMap<>();for(String k:List.of("name","employeeType","remark")){String s=WorkProjectService.text(input,k);if(s.length()>(k.equals("remark")?2000:100)||(!k.equals("remark")&&s.isEmpty()))throw new ServiceException("姓名和类型必填且不能超过100字");v.put(k,s);}Object active=input.getOrDefault("active",Boolean.TRUE);if(!(active instanceof Boolean))throw new ServiceException("人员状态无效");v.put("active",active);v.put("actor",SecurityUtils.getUsername());Long id=WorkProjectService.number(input.get("id"));if(id==null)mapper.add(v);else{v.put("id",id);v.put("version",WorkProjectService.number(input.get("version")));if(mapper.edit(v)!=1)throw new ServiceException("人员已修改，请刷新重试");}return success(v.get("id"));}
}
